import React, { useState } from 'react';
import { motion } from 'framer-motion';
import AnimatedText from '../components/AnimatedText';
import { ChevronLeft, ChevronRight, Calendar as CalendarIcon, Clock } from 'lucide-react';
import './Booking.css';

const Booking = () => {
  const [selectedDate, setSelectedDate] = useState(null);
  const [currentMonth, setCurrentMonth] = useState(new Date());
  
  // Dummy calendar generation (just visual)
  const daysInMonth = new Date(currentMonth.getFullYear(), currentMonth.getMonth() + 1, 0).getDate();
  const firstDay = new Date(currentMonth.getFullYear(), currentMonth.getMonth(), 1).getDay();
  
  const days = Array.from({ length: daysInMonth }, (_, i) => i + 1);
  const padding = Array.from({ length: firstDay }, (_, i) => i);

  const monthNames = ["January", "February", "March", "April", "May", "June",
    "July", "August", "September", "October", "November", "December"
  ];

  const handlePrevMonth = () => {
    setCurrentMonth(new Date(currentMonth.getFullYear(), currentMonth.getMonth() - 1));
  };

  const handleNextMonth = () => {
    setCurrentMonth(new Date(currentMonth.getFullYear(), currentMonth.getMonth() + 1));
  };

  return (
    <div className="page section-padding">
      <div className="container booking-container">
        <div className="booking-header">
          <AnimatedText text="Book a Session" el="h1" className="booking-title" />
          <motion.p 
            initial={{ opacity: 0 }} animate={{ opacity: 1 }} transition={{ delay: 0.3 }}
            className="booking-subtitle"
          >
            Select a date to check availability and request a booking.
          </motion.p>
        </div>

        <div className="booking-content">
          <motion.div 
            className="calendar-section"
            initial={{ opacity: 0, x: -30 }} animate={{ opacity: 1, x: 0 }} transition={{ duration: 0.8 }}
          >
            <div className="calendar-header">
              <button className="interactive" onClick={handlePrevMonth}><ChevronLeft /></button>
              <h3>{monthNames[currentMonth.getMonth()]} {currentMonth.getFullYear()}</h3>
              <button className="interactive" onClick={handleNextMonth}><ChevronRight /></button>
            </div>
            
            <div className="calendar-grid">
              {['Su', 'Mo', 'Tu', 'We', 'Th', 'Fr', 'Sa'].map(day => (
                <div key={day} className="day-name">{day}</div>
              ))}
              
              {padding.map((_, i) => <div key={`pad-${i}`} className="day empty" />)}
              
              {days.map(day => {
                const date = new Date(currentMonth.getFullYear(), currentMonth.getMonth(), day);
                const isPast = date < new Date().setHours(0,0,0,0);
                const isSelected = selectedDate && date.toDateString() === selectedDate.toDateString();
                
                return (
                  <button 
                    key={day}
                    disabled={isPast}
                    className={`day interactive ${isSelected ? 'selected' : ''} ${isPast ? 'disabled' : ''}`}
                    onClick={() => setSelectedDate(date)}
                  >
                    {day}
                  </button>
                )
              })}
            </div>
          </motion.div>

          <motion.div 
            className="form-section"
            initial={{ opacity: 0, x: 30 }} animate={{ opacity: 1, x: 0 }} transition={{ duration: 0.8 }}
          >
            {selectedDate ? (
              <form className="booking-form" onSubmit={(e) => { e.preventDefault(); alert("Booking request sent!"); }}>
                <div className="selected-date-display">
                  <CalendarIcon className="icon-accent" />
                  <span>{selectedDate.toLocaleDateString('en-US', { weekday: 'long', month: 'long', day: 'numeric', year: 'numeric' })}</span>
                </div>
                
                <div className="form-group">
                  <label>Session Type</label>
                  <select required className="interactive">
                    <option value="">Select a type...</option>
                    <option value="wedding">Wedding Coverage</option>
                    <option value="pre-wedding">Pre-Wedding Shoot</option>
                    <option value="maternity">Maternity Shoot</option>
                    <option value="baby">Baby/Newborn Shoot</option>
                    <option value="events">Event Photography</option>
                    <option value="corporate">Corporate Headshots/Events</option>
                    <option value="product">Product Photography</option>
                  </select>
                </div>

                <div className="form-row">
                  <div className="form-group">
                    <label>Start Time</label>
                    <div className="time-input-wrapper">
                      <Clock className="input-icon" size={16} />
                      <select required className="interactive">
                        <option value="09:00">09:00 AM</option>
                        <option value="11:00">11:00 AM</option>
                        <option value="14:00">02:00 PM</option>
                        <option value="16:00">04:00 PM</option>
                      </select>
                    </div>
                  </div>
                  <div className="form-group">
                    <label>Duration</label>
                    <select required className="interactive">
                      <option value="2">2 Hours</option>
                      <option value="4">Half Day (4 Hrs)</option>
                      <option value="8">Full Day (8 Hrs)</option>
                    </select>
                  </div>
                </div>

                <div className="form-group">
                  <input type="text" placeholder="Your Full Name" required className="interactive" />
                </div>
                <div className="form-group">
                  <input type="email" placeholder="Email Address" required className="interactive" />
                </div>

                <button type="submit" className="submit-btn interactive">Request Booking</button>
              </form>
            ) : (
              <div className="no-date-selected">
                <CalendarIcon size={48} className="icon-muted" />
                <p>Please select a date from the calendar to view availability and book a session.</p>
              </div>
            )}
          </motion.div>
        </div>
      </div>
    </div>
  );
};

export default Booking;
